-- BMLT NHPC bulk question bank and notes
-- Source alignment: NHPC B.Sc. MLT/BMLT licensing syllabus (official syllabus topics).
-- This batch contains 148 unique practice MCQs, 142 distinct mock questions, and 32 bilingual notes.
-- Faculty and subject are intentionally separate from the PCL CMLT/DMLT module.
-- Safe to rerun: content_id conflicts update the corresponding record.
begin;
on conflict (content_id) do update set
 faculty=excluded.faculty,
 subject=excluded.subject,
 content_type=excluded.content_type,
 access_tier=excluded.access_tier,
 display_order=excluded.display_order,
 content_data=excluded.content_data,
 is_published=excluded.is_published,
 updated_at=now();
commit;

-- Verification:
select faculty,subject,content_type,count(*) as total
from public.learning_content
where faculty='BMLT' and subject='BMLT NHPC Licensing'
group by faculty,subject,content_type
order by content_type;
