('bmlt-nhpc-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"The main site of haematopoiesis in adults is:","translation":"वयस्कमा रक्तकोष निर्माणको मुख्य स्थान कुन हो?","options":["Bone marrow","Spleen only","Liver only","Kidney"],"correctIndex":0,"explanation":"Bone marrow is the principal site of blood-cell production in adults.","explanationNe":"वयस्कमा रक्तकोष निर्माणको मुख्य स्थान bone marrow हो।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"Which anticoagulant is commonly used for a CBC?","translation":"CBC का लागि सामान्यतया कुन anticoagulant प्रयोग हुन्छ?","options":["EDTA","Sodium fluoride","Plain tube","Sodium citrate only"],"correctIndex":0,"explanation":"EDTA preserves cellular morphology and is commonly used for CBC specimens.","explanationNe":"EDTA ले रक्तकोषको स्वरूप जोगाउँछ र CBC मा प्रयोग हुन्छ।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"MCV indicates the:","translation":"MCV ले के जनाउँछ?","options":["Average red-cell volume","Platelet count","Total WBC count","Plasma glucose"],"correctIndex":0,"explanation":"MCV is the mean corpuscular volume, an estimate of average red-cell size.","explanationNe":"MCV ले RBC को औसत आकार जनाउँछ।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"Which cell is primarily responsible for oxygen transport?","translation":"अक्सिजन बोक्ने मुख्य कोष कुन हो?","options":["Erythrocyte","Neutrophil","Platelet","Lymphocyte"],"correctIndex":0,"explanation":"Erythrocytes contain haemoglobin that transports oxygen.","explanationNe":"Erythrocyte मा haemoglobin हुन्छ जसले अक्सिजन बोक्छ।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"Which test is commonly used to assess the extrinsic coagulation pathway?","translation":"Extrinsic coagulation pathway जाँच्न कुन परीक्षण प्रयोग हुन्छ?","options":["PT/INR","aPTT","ESR","Reticulocyte count"],"correctIndex":0,"explanation":"PT evaluates the extrinsic and common coagulation pathways.","explanationNe":"PT ले extrinsic र common coagulation pathway जाँच गर्छ।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"Reticulocytes are:","translation":"Reticulocyte भनेको के हो?","options":["Immature red blood cells","Mature neutrophils","Platelet fragments","Plasma proteins"],"correctIndex":0,"explanation":"Reticulocytes are young red cells recently released from bone marrow.","explanationNe":"Reticulocyte bone marrow बाट भर्खर निस्केका अपरिपक्व RBC हुन्।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"A common microcytic anaemia is associated with deficiency of:","translation":"Microcytic anaemia को सामान्य कारण कुन तत्वको कमी हो?","options":["Iron","Vitamin C","Vitamin K","Sodium"],"correctIndex":0,"explanation":"Iron deficiency commonly causes microcytic hypochromic anaemia.","explanationNe":"Iron कमीले प्रायः microcytic hypochromic anaemia गराउँछ।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"Which plasma component is essential for clot formation?","translation":"रगत जम्न कुन plasma component आवश्यक हुन्छ?","options":["Fibrinogen","Albumin","Glucose","Urea"],"correctIndex":0,"explanation":"Fibrinogen is converted to fibrin during coagulation.","explanationNe":"Coagulation हुँदा fibrinogen fibrin मा परिवर्तन हुन्छ।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Which anticoagulant is commonly used for coagulation testing?","translation":"Coagulation परीक्षणमा सामान्यतया कुन anticoagulant प्रयोग हुन्छ?","options":["Sodium citrate","EDTA","Heparin for all tests","Fluoride oxalate"],"correctIndex":0,"explanation":"Citrate binds calcium reversibly and is used for coagulation assays.","explanationNe":"Citrate ले calcium लाई reversible रूपमा बाँध्छ र coagulation परीक्षणमा प्रयोग हुन्छ।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"The primary function of platelets is:","translation":"Platelet को मुख्य काम के हो?","options":["Primary haemostasis","Oxygen transport","Antibody production","Bilirubin conjugation"],"correctIndex":0,"explanation":"Platelets form the initial platelet plug at sites of vascular injury.","explanationNe":"रक्तनलीमा चोट लाग्दा platelet ले प्रारम्भिक plug बनाउँछ।","topic":"Haematology"}'::jsonb,true),
('bmlt-nhpc-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Beer-Lambert law relates absorbance to:","translation":"Beer-Lambert law ले absorbance लाई केसँग सम्बन्धित गर्छ?","options":["Concentration and path length","Temperature only","Blood pressure","Centrifuge speed"],"correctIndex":0,"explanation":"Absorbance is proportional to concentration and optical path length within the valid range.","explanationNe":"मान्य दायरामा absorbance, concentration र optical path length सँग समानुपाती हुन्छ।","topic":"Biochemistry"}'::jsonb,true),
