('bmlt-nhpc-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Creatinine is mainly used to assess:","translation":"Creatinine मुख्यतः के मूल्याङ्कन गर्न प्रयोग हुन्छ?","options":["Renal function","Lung function","Thyroid function","Coagulation"],"correctIndex":0,"explanation":"Serum creatinine contributes to assessment of kidney function and eGFR.","explanationNe":"Serum creatinine मिर्गौलाको कार्य र eGFR मूल्याङ्कनमा प्रयोग हुन्छ।","topic":"Biochemistry"}'::jsonb,true),
('bmlt-nhpc-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"Which sample preservative helps reduce glycolysis in glucose testing?","translation":"Glucose परीक्षणमा glycolysis घटाउन कुन preservative प्रयोग गरिन्छ?","options":["Sodium fluoride (often with an anticoagulant)","EDTA alone in every method","Formalin","Distilled water"],"correctIndex":0,"explanation":"Fluoride inhibits glycolysis; follow the laboratory''s validated tube and processing protocol.","explanationNe":"Fluoride ले glycolysis रोक्छ; प्रयोगशालाको प्रमाणित tube र processing protocol पालना गर्नुहोस्।","topic":"Biochemistry"}'::jsonb,true),
