('bmlt-nhpc-mcq-141','BMLT','BMLT NHPC Licensing','mcq','free',141,'{"question":"What is the main purpose of a laboratory centrifuge?","translation":"Laboratory centrifuge को मुख्य उद्देश्य के हो?","options":["Separate components by centrifugal sedimentation","Sterilise glassware","Measure pH","Amplify DNA"],"correctIndex":0,"explanation":"Centrifugation separates particles according to sedimentation under centrifugal force.","explanationNe":"Centrifugation ले centrifugal force अन्तर्गत sedimentation का आधारमा कण छुट्याउँछ।","topic":"Instrumentation"}'::jsonb,true),
('bmlt-nhpc-mock-136','BMLT','BMLT NHPC Licensing','mock','free',136,'{"question":"Which instrument measures the pH of a solution?","translation":"Solution को pH मापन गर्ने उपकरण कुन हो?","options":["pH meter","Colorimeter","Haemocytometer","Incubator"],"correctIndex":0,"explanation":"A pH meter uses an electrode system and requires calibration.","explanationNe":"pH meter ले electrode system प्रयोग गर्छ र calibration आवश्यक हुन्छ।","topic":"Instrumentation"}'::jsonb,true),
('bmlt-nhpc-mcq-142','BMLT','BMLT NHPC Licensing','mcq','free',142,'{"question":"Many human bacterial pathogens are routinely incubated near which temperature?","translation":"धेरै मानव रोगजनक जीवाणु कुन तापक्रम नजिक incubate गरिन्छ?","options":["35–37°C","4°C","60°C","Below 0°C"],"correctIndex":0,"explanation":"Many human pathogens grow near body temperature, though optimum conditions vary.","explanationNe":"धेरै मानव रोगजनक जीवाणु शरीरको तापक्रम नजिक बढ्छन्, तर optimum condition फरक हुन सक्छ।","topic":"Instrumentation"}'::jsonb,true),
('bmlt-nhpc-mock-137','BMLT','BMLT NHPC Licensing','mock','free',137,'{"question":"Which document describes a standard step-by-step laboratory test procedure?","translation":"Laboratory test को standard चरणबद्ध विधि कुन document मा हुन्छ?","options":["Standard operating procedure (SOP)","Patient appointment card","Purchase invoice","Duty roster"],"correctIndex":0,"explanation":"An SOP standardises procedures, responsibilities, quality checks and documentation.","explanationNe":"SOP ले procedure, जिम्मेवारी, quality check र documentation standard बनाउँछ।","topic":"Laboratory Management"}'::jsonb,true),
('bmlt-nhpc-mcq-143','BMLT','BMLT NHPC Licensing','mcq','free',143,'{"question":"What is the main purpose of internal quality control?","translation":"Internal quality control को मुख्य उद्देश्य के हो?","options":["Monitor analytical performance and detect errors","Replace external quality assessment","Diagnose without specimens","Increase turnaround time"],"correctIndex":0,"explanation":"Internal QC monitors the analytical process before patient results are released.","explanationNe":"Internal QC ले patient result जारी गर्नुअघि analytical process निगरानी गर्छ।","topic":"Laboratory Management"}'::jsonb,true),
('bmlt-nhpc-mock-138','BMLT','BMLT NHPC Licensing','mock','free',138,'{"question":"What should be done when a QC result is outside acceptable limits?","translation":"QC result स्वीकार्य सीमाभन्दा बाहिर आएमा के गर्नुपर्छ?","options":["Hold results and investigate the cause","Release all patient results","Alter results manually","Ignore the control"],"correctIndex":0,"explanation":"Out-of-control results require investigation and corrective action before affected results are released.","explanationNe":"Control result सीमा बाहिर हुँदा कारण खोजी र corrective action पछि मात्र प्रभावित नतिजा जारी गर्नुपर्छ।","topic":"Laboratory Management"}'::jsonb,true),
('bmlt-nhpc-mcq-144','BMLT','BMLT NHPC Licensing','mcq','free',144,'{"question":"Which blood component contains multiple coagulation factors?","translation":"धेरै coagulation factor भएको blood component कुन हो?","options":["Fresh frozen plasma","Packed red cells","Platelet concentrate","Washed red cells"],"correctIndex":0,"explanation":"Fresh frozen plasma contains multiple clotting factors and is used for selected indications.","explanationNe":"Fresh frozen plasma मा धेरै clotting factor हुन्छ र निश्चित indication मा प्रयोग हुन्छ।","topic":"Blood Banking"}'::jsonb,true),
('bmlt-nhpc-mock-139','BMLT','BMLT NHPC Licensing','mock','free',139,'{"question":"Which antigen is especially important in the Rh blood group system?","translation":"Rh blood group system मा कुन antigen विशेष महत्त्वपूर्ण हुन्छ?","options":["D antigen","A antigen","B antigen","H antigen"],"correctIndex":0,"explanation":"RhD status depends on the presence or absence of D antigen on red cells.","explanationNe":"Red cell मा D antigen छ वा छैन भन्ने आधारमा RhD status निर्धारण हुन्छ।","topic":"Blood Banking"}'::jsonb,true),
('bmlt-nhpc-mcq-145','BMLT','BMLT NHPC Licensing','mcq','free',145,'{"question":"What is the immediate action when an acute transfusion reaction is suspected?","translation":"Acute transfusion reaction को शंका हुँदा तत्काल के गर्नुपर्छ?","options":["Stop the transfusion and assess the patient","Increase the transfusion rate","Continue until empty","Discard the bag without reporting"],"correctIndex":0,"explanation":"Stop transfusion, assess the patient and notify the clinical/transfusion team.","explanationNe":"Transfusion रोक्नुहोस्, बिरामी जाँच्नुहोस् र clinical/transfusion team लाई खबर गर्नुहोस्।","topic":"Blood Banking"}'::jsonb,true),
('bmlt-nhpc-mcq-146','BMLT','BMLT NHPC Licensing','mcq','free',146,'{"question":"Which term describes malignant growth with potential tissue invasion and spread?","translation":"Tissue invasion र फैलिने सम्भावना भएको malignant growth लाई के भनिन्छ?","options":["Malignant neoplasia","Physiological hypertrophy","Atrophy","Simple hyperplasia"],"correctIndex":0,"explanation":"Malignant neoplasms may invade adjacent tissues and metastasise.","explanationNe":"Malignant neoplasm नजिकका tissue मा invasion र metastasis गर्न सक्छ।","topic":"Pathology"}'::jsonb,true),
('bmlt-nhpc-mock-140','BMLT','BMLT NHPC Licensing','mock','free',140,'{"question":"Which type of necrosis is typical of myocardial infarction?","translation":"Myocardial infarction मा सामान्यतया कुन प्रकारको necrosis हुन्छ?","options":["Coagulative necrosis","Caseous necrosis","Fat necrosis","Fibrinoid necrosis"],"correctIndex":0,"explanation":"Ischaemia in most solid organs, including myocardium, produces coagulative necrosis; brain is an exception.","explanationNe":"मुटुसहित धेरै solid organ को ischaemia ले coagulative necrosis गराउँछ; brain अपवाद हो।","topic":"Pathology"}'::jsonb,true),
('bmlt-nhpc-mcq-147','BMLT','BMLT NHPC Licensing','mcq','free',147,'{"question":"Which organelle generates most cellular ATP by oxidative phosphorylation?","translation":"Oxidative phosphorylation बाट धेरैजसो cellular ATP उत्पादन गर्ने organelle कुन हो?","options":["Mitochondrion","Ribosome","Lysosome","Golgi apparatus"],"correctIndex":0,"explanation":"Mitochondria generate most ATP in aerobic cells through oxidative phosphorylation.","explanationNe":"Aerobic cell मा mitochondria ले oxidative phosphorylation मार्फत धेरै ATP उत्पादन गर्छ।","topic":"Anatomy and Physiology"}'::jsonb,true),
('bmlt-nhpc-mock-141','BMLT','BMLT NHPC Licensing','mock','free',141,'{"question":"Which brain structure is important for balance and coordination?","translation":"सन्तुलन र समन्वयका लागि कुन brain structure महत्त्वपूर्ण हुन्छ?","options":["Cerebellum","Medulla","Hypothalamus","Occipital lobe"],"correctIndex":0,"explanation":"The cerebellum coordinates movement, posture and balance.","explanationNe":"Cerebellum ले movement, posture र balance समन्वय गर्छ।","topic":"Anatomy and Physiology"}'::jsonb,true),
('bmlt-nhpc-mcq-148','BMLT','BMLT NHPC Licensing','mcq','free',148,'{"question":"Which hormone increases serum calcium through effects on bone and kidney?","translation":"हड्डी र मिर्गौलामा प्रभाव पारेर serum calcium बढाउने hormone कुन हो?","options":["Parathyroid hormone","Insulin","Aldosterone","Melatonin"],"correctIndex":0,"explanation":"Parathyroid hormone raises serum calcium and indirectly increases intestinal absorption via vitamin D.","explanationNe":"Parathyroid hormone ले serum calcium बढाउँछ र vitamin D मार्फत intestinal absorption बढाउँछ।","topic":"Anatomy and Physiology"}'::jsonb,true),
('bmlt-nhpc-mock-142','BMLT','BMLT NHPC Licensing','mock','free',142,'{"question":"Which chamber pumps oxygenated blood into the aorta?","translation":"Aorta मा oxygenated blood पम्प गर्ने heart chamber कुन हो?","options":["Left ventricle","Right ventricle","Right atrium","Left atrium"],"correctIndex":0,"explanation":"The left ventricle pumps oxygenated blood through the aortic valve into systemic circulation.","explanationNe":"Left ventricle ले aortic valve हुँदै oxygenated blood systemic circulation मा पठाउँछ।","topic":"Anatomy and Physiology"}'::jsonb,true),
('bmlt-nhpc-note-01','BMLT','BMLT NHPC Licensing','note','free',1,'{"title":"Introduction to clinical laboratory","english":"Clinical laboratory testing supports screening, diagnosis, prognosis and monitoring. Results must be interpreted with clinical findings and the laboratory''s validated reference intervals.","nepali":"Clinical laboratory ले screening, diagnosis, prognosis र monitoring मा सहयोग गर्छ। नतिजा बिरामीको अवस्था र प्रयोगशालाको प्रमाणित reference interval सँगै व्याख्या गर्नुपर्छ।"}'::jsonb,true),
('bmlt-nhpc-note-02','BMLT','BMLT NHPC Licensing','note','free',2,'{"title":"Laboratory safety and PPE","english":"Perform hand hygiene, use task-appropriate PPE, never mouth-pipette, handle sharps safely and follow spill, exposure and waste procedures. Treat all specimens as potentially infectious.","nepali":"हात सफा गर्नुहोस्, कामअनुसार PPE लगाउनुहोस्, मुखले pipette नगर्नुहोस्, sharps सुरक्षित सम्हाल्नुहोस् र spill/exposure तथा फोहोर व्यवस्थापनका नियम पालना गर्नुहोस्। सबै नमुनालाई सम्भावित संक्रमित मान्नुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-03','BMLT','BMLT NHPC Licensing','note','free',3,'{"title":"Specimen identification and collection","english":"Use at least two approved patient identifiers, collect the correct specimen in the correct container, label at collection and document date/time and collector according to policy.","nepali":"कम्तीमा दुई स्वीकृत पहिचान विवरण प्रयोग गर्नुहोस्। सही नमुना सही container मा संकलन गरी संकलनकै समयमा label लगाउनुहोस् र मिति/समय तथा संकलक अभिलेख गर्नुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-04','BMLT','BMLT NHPC Licensing','note','free',4,'{"title":"Pre-analytical errors","english":"Wrong patient, wrong tube, hemolysis, clotting, insufficient volume, contamination, delayed transport and improper storage can invalidate results.","nepali":"गलत बिरामी, गलत tube, hemolysis, clot, कम मात्रा, contamination, ढिलो ढुवानी र गलत भण्डारणले नतिजा बिगार्न सक्छ।"}'::jsonb,true),
('bmlt-nhpc-note-05','BMLT','BMLT NHPC Licensing','note','free',5,'{"title":"Centrifugation","english":"Centrifugation separates components by density using centrifugal force. Balance opposing tubes, use appropriate speed/time and wait until the rotor stops before opening.","nepali":"Centrifugation ले centrifugal force प्रयोग गरी घनत्वअनुसार घटक छुट्याउँछ। विपरीत tube सन्तुलन गर्नुहोस्, उचित speed/time छान्नुहोस् र rotor पूर्ण रोकिएपछि मात्र खोल्नुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-06','BMLT','BMLT NHPC Licensing','note','free',6,'{"title":"Pipettes and volumetric accuracy","english":"Use calibrated pipettes within their specified range, change tips between samples, avoid bubbles and follow correct aspiration/dispensing technique.","nepali":"प्रमाणित pipette यसको तोकिएको range भित्र प्रयोग गर्नुहोस्, नमुनाबीच tip फेर्नुहोस्, bubble नबनाउनुहोस् र aspiration/dispensing विधि पालना गर्नुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-07','BMLT','BMLT NHPC Licensing','note','free',7,'{"title":"Photometry and Beer-Lambert law","english":"Photometry estimates analyte concentration from light absorption. Within its working range, absorbance is proportional to concentration and path length under Beer-Lambert law.","nepali":"Photometry ले प्रकाश अवशोषणबाट पदार्थको concentration अनुमान गर्छ। Beer-Lambert law अनुसार उपयुक्त दायरामा absorbance, concentration र path length सँग समानुपाती हुन्छ।"}'::jsonb,true),
('bmlt-nhpc-note-08','BMLT','BMLT NHPC Licensing','note','free',8,'{"title":"Clinical biochemistry: glucose","english":"Blood glucose testing helps diagnose and monitor diabetes. Fasting status, sample type, glycolysis and prompt separation affect results; use validated diagnostic criteria.","nepali":"Blood glucose परीक्षणले diabetes निदान र निगरानीमा मद्दत गर्छ। fasting अवस्था, नमुनाको प्रकार, glycolysis र समयमै separation ले नतिजा असर गर्छ; मान्य diagnostic criteria प्रयोग गर्नुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-09','BMLT','BMLT NHPC Licensing','note','free',9,'{"title":"Renal function tests","english":"Urea and creatinine are used to assess renal function, interpreted with hydration, muscle mass, age and estimated GFR where appropriate.","nepali":"Urea र creatinine मिर्गौलाको कार्य मूल्याङ्कनमा प्रयोग हुन्छन्। hydration, muscle mass, उमेर र आवश्यकताअनुसार eGFR सँगै व्याख्या गर्नुपर्छ।"}'::jsonb,true),
('bmlt-nhpc-note-10','BMLT','BMLT NHPC Licensing','note','free',10,'{"title":"Liver function tests","english":"ALT, AST, ALP, bilirubin and albumin provide different information about hepatocellular injury, cholestasis and synthetic function; no single test describes all liver function.","nepali":"ALT, AST, ALP, bilirubin र albumin ले hepatocellular injury, cholestasis र synthetic function बारे फरक जानकारी दिन्छन्; एउटै परीक्षणले सम्पूर्ण liver function बताउँदैन।"}'::jsonb,true),
('bmlt-nhpc-note-11','BMLT','BMLT NHPC Licensing','note','free',11,'{"title":"Quality control in biochemistry","english":"Run appropriate internal quality control, review control charts and investigate out-of-range controls before releasing patient results. Participate in external quality assessment where available.","nepali":"उपयुक्त internal quality control चलाउनुहोस्, control chart समीक्षा गर्नुहोस् र control सीमा बाहिर भए patient result जारी गर्नुअघि कारण खोज्नुहोस्। उपलब्ध भए external quality assessment मा सहभागी हुनुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-12','BMLT','BMLT NHPC Licensing','note','free',12,'{"title":"Haematopoiesis and blood cells","english":"Haematopoiesis is blood-cell production, mainly in bone marrow after birth. Red cells carry oxygen, white cells defend against infection and platelets support haemostasis.","nepali":"Haematopoiesis भनेको रक्तकोष निर्माण हो, जन्मपछि मुख्यतः bone marrow मा हुन्छ। RBC ले अक्सिजन बोक्छ, WBC ले संक्रमणविरुद्ध रक्षा गर्छ र platelet ले haemostasis मा सहयोग गर्छ।"}'::jsonb,true),
('bmlt-nhpc-note-13','BMLT','BMLT NHPC Licensing','note','free',13,'{"title":"Anaemia and red cell indices","english":"Anaemia is reduced haemoglobin relative to appropriate reference criteria. MCV describes average red-cell volume; MCH and MCHC describe haemoglobin content/concentration.","nepali":"उपयुक्त मापदण्डअनुसार haemoglobin घट्नु anaemia हो। MCV ले RBC को औसत आकार, MCH र MCHC ले haemoglobin को मात्रा/सान्द्रता जनाउँछन्।"}'::jsonb,true),
('bmlt-nhpc-note-14','BMLT','BMLT NHPC Licensing','note','free',14,'{"title":"Peripheral blood smear","english":"A well-made, properly stained blood film helps assess red-cell morphology, white-cell differential and platelet appearance. Avoid thick, uneven or poorly dried films.","nepali":"राम्रोसँग बनाइएको र रंगाइएको blood film ले RBC morphology, WBC differential र platelet को स्वरूप जाँच्न मद्दत गर्छ। धेरै बाक्लो, असमान वा राम्रोसँग नसुकाइएको smear नबनाउनुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-15','BMLT','BMLT NHPC Licensing','note','free',15,'{"title":"Coagulation tests","english":"PT/INR evaluates the extrinsic and common pathways; aPTT evaluates the intrinsic and common pathways. Interpret results with medication history and clinical context.","nepali":"PT/INR ले extrinsic र common pathway, aPTT ले intrinsic र common pathway मूल्याङ्कन गर्छ। औषधि इतिहास र clinical अवस्थासँगै नतिजा बुझ्नुपर्छ।"}'::jsonb,true),
('bmlt-nhpc-note-16','BMLT','BMLT NHPC Licensing','note','free',16,'{"title":"Bacteriology and culture","english":"Aseptic collection and prompt transport improve culture yield. Culture media support microbial growth; identification and antimicrobial susceptibility testing follow validated methods.","nepali":"Aseptic संकलन र छिटो ढुवानीले culture को गुणस्तर बढाउँछ। Culture media ले सूक्ष्मजीव बढ्न सहयोग गर्छ; identification र antimicrobial susceptibility परीक्षण मान्य विधिअनुसार गर्नुपर्छ।"}'::jsonb,true),
('bmlt-nhpc-note-17','BMLT','BMLT NHPC Licensing','note','free',17,'{"title":"Staining and microscopy","english":"Gram stain differentiates many bacteria by cell-wall properties. Microscopy findings are presumptive and should be correlated with culture and other tests when indicated.","nepali":"Gram stain ले cell-wall विशेषताका आधारमा धेरै bacteria छुट्याउँछ। Microscopy का निष्कर्ष प्रारम्भिक हुन सक्छन्; आवश्यकताअनुसार culture र अन्य परीक्षणसँग मिलाएर व्याख्या गर्नुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-18','BMLT','BMLT NHPC Licensing','note','free',18,'{"title":"Immunology and serology","english":"Antigen-antibody reactions underpin tests such as agglutination and ELISA. A reactive screening result may require confirmatory testing according to the diagnostic algorithm.","nepali":"Antigen-antibody reaction agglutination र ELISA जस्ता परीक्षणको आधार हो। Reactive screening नतिजामा diagnostic algorithm अनुसार confirmatory test आवश्यक हुन सक्छ।"}'::jsonb,true),
('bmlt-nhpc-note-19','BMLT','BMLT NHPC Licensing','note','free',19,'{"title":"Clinical parasitology","english":"Stool, blood and other specimens are selected according to suspected parasite and life cycle. Timing, preservation, concentration and microscopy technique influence detection.","nepali":"शंका गरिएको परजीवी र यसको life cycle अनुसार दिसा, रगत वा अन्य नमुना छानिन्छ। समय, preservation, concentration र microscopy विधिले पहिचानमा प्रभाव पार्छ।"}'::jsonb,true),
('bmlt-nhpc-note-20','BMLT','BMLT NHPC Licensing','note','free',20,'{"title":"Urinalysis and body fluids","english":"Urinalysis includes physical, chemical and microscopic examination. CSF and other body fluids require correct collection, urgent transport when indicated and interpretation with clinical context.","nepali":"Urinalysis मा physical, chemical र microscopic परीक्षण पर्छ। CSF तथा अन्य body fluid सही तरिकाले संकलन गर्नुपर्छ; आवश्यक अवस्थामा तुरुन्त ढुवानी गरी clinical अवस्थासँगै व्याख्या गर्नुपर्छ।"}'::jsonb,true),
('bmlt-nhpc-note-21','BMLT','BMLT NHPC Licensing','note','free',21,'{"title":"Clinical biochemistry: electrolytes and acid–base balance","english":"Sodium is the major extracellular cation and potassium the major intracellular cation. Calcium is important for neuromuscular function and coagulation; bicarbonate is a major buffer. Interpret electrolyte results with specimen quality, renal function, medications and clinical status. Blood-gas interpretation considers pH, pCO2 and bicarbonate to identify respiratory or metabolic disturbances; compensation does not necessarily mean the primary disorder has resolved.","nepali":"Sodium मुख्य extracellular cation र potassium मुख्य intracellular cation हो। Calcium स्नायु-मांसपेशी कार्य र coagulation का लागि महत्त्वपूर्ण हुन्छ; bicarbonate प्रमुख buffer हो। Electrolyte नतिजा नमुनाको गुणस्तर, मिर्गौला कार्य, औषधि र बिरामीको अवस्थासँगै व्याख्या गर्नुपर्छ। Blood gas मा pH, pCO2 र bicarbonate हेरेर respiratory वा metabolic समस्या पहिचान गरिन्छ।"}'::jsonb,true),
('bmlt-nhpc-note-22','BMLT','BMLT NHPC Licensing','note','free',22,'{"title":"Clinical biochemistry: enzymes and endocrine tests","english":"ALT and AST are markers of hepatocellular injury, while ALP and GGT together may support a cholestatic or hepatobiliary pattern. Serum lipase is commonly used in suspected acute pancreatitis. TSH with free T4 helps assess thyroid function; HbA1c estimates average glycaemia over roughly 2–3 months but may be affected by altered red-cell survival. Always interpret results using the laboratory''s validated intervals and clinical context.","nepali":"ALT र AST ले liver cell injury जनाउन सक्छन्; ALP र GGT दुवै बढ्दा cholestatic वा hepatobiliary pattern को समर्थन हुन्छ। Acute pancreatitis शंकामा serum lipase प्रयोग गरिन्छ। TSH र free T4 ले thyroid function मूल्याङ्कन गर्छन्; HbA1c ले करिब २–३ महिनाको औसत glucose देखाउँछ तर RBC को आयु बदलिँदा प्रभावित हुन सक्छ। नतिजा प्रयोगशालाको मान्य reference interval र clinical अवस्था अनुसार व्याख्या गर्नुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-23','BMLT','BMLT NHPC Licensing','note','free',23,'{"title":"Haematology: blood film and reticulocyte count","english":"A peripheral blood film assesses red-cell morphology, white-cell appearance, platelet estimate and abnormal cells. Microcytosis and hypochromia commonly occur in iron deficiency; macro-ovalocytes and hypersegmented neutrophils suggest megaloblastic change. Reticulocytes reflect marrow response: an increased count may follow haemolysis or blood loss, while a low response may occur when marrow production is impaired. Correlate the film with CBC indices and clinical findings.","nepali":"Peripheral blood film ले RBC को आकार, WBC को स्वरूप, platelet को अनुमान र असामान्य कोषिका हेर्छ। Iron deficiency मा प्रायः microcytic hypochromic RBC देखिन्छ; macro-ovalocyte र hypersegmented neutrophil ले megaloblastic परिवर्तन संकेत गर्छ। Reticulocyte ले bone marrow को प्रतिक्रिया देखाउँछ; haemolysis वा रक्तस्रावपछि बढ्न सक्छ, उत्पादन घट्दा कम हुन सक्छ। CBC indices र clinical अवस्था सँगै हेर्नुपर्छ।"}'::jsonb,true),
('bmlt-nhpc-note-24','BMLT','BMLT NHPC Licensing','note','free',24,'{"title":"Haematology: haemostasis and coagulation","english":"Primary haemostasis involves platelet adhesion, activation and aggregation; secondary haemostasis generates fibrin through coagulation pathways. PT/INR is commonly used to monitor vitamin K antagonist therapy, while aPTT evaluates intrinsic and common pathway factors and may monitor unfractionated heparin under protocol. Citrated plasma is used for routine coagulation tests with the correct blood-to-anticoagulant ratio. Underfilled tubes can prolong results falsely.","nepali":"Primary haemostasis मा platelet टाँसिने, सक्रिय हुने र एकत्रित हुने प्रक्रिया पर्छ; secondary haemostasis मा coagulation pathway बाट fibrin बन्छ। Vitamin K antagonist उपचारमा PT/INR र intrinsic/common pathway मूल्याङ्कनमा aPTT प्रयोग हुन्छ; unfractionated heparin monitoring protocol अनुसार aPTT बाट हुन सक्छ। Coagulation परीक्षणमा सही blood-to-citrate अनुपात भएको citrate plasma चाहिन्छ। कम भरिएको tube ले नतिजा गलत रूपमा लम्ब्याउन सक्छ।"}'::jsonb,true),
('bmlt-nhpc-note-25','BMLT','BMLT NHPC Licensing','note','free',25,'{"title":"Clinical microbiology: specimen processing and culture","english":"Choose specimens from the actual site of infection and collect them before antimicrobial therapy when clinically safe. Use aseptic technique, appropriate containers and prompt transport. Culture media, atmosphere and incubation conditions depend on the suspected organism. A culture identifies organisms that grow under the conditions used; a negative culture does not always exclude infection. Report significant isolates with appropriate identification and susceptibility results.","nepali":"संक्रमण भएको वास्तविक स्थानबाट नमुना छान्नुहोस् र चिकित्सकीय रूपमा सुरक्षित भए antimicrobial सुरु गर्नुअघि संकलन गर्नुहोस्। Aseptic technique, उपयुक्त container र छिटो ढुवानी अपनाउनुहोस्। Culture media, वातावरण र incubation अवस्था शंकास्पद जीवअनुसार फरक हुन्छ। Culture मा प्रयोग गरिएको अवस्थामा बढ्ने जीव मात्र पत्ता लाग्छ; negative culture ले सधैँ संक्रमण छैन भन्ने प्रमाणित गर्दैन।"}'::jsonb,true),
('bmlt-nhpc-note-26','BMLT','BMLT NHPC Licensing','note','free',26,'{"title":"Immunology: antigen–antibody reactions and quality","english":"Antigens bind specifically to antibodies. Common laboratory reactions include agglutination, precipitation, immunofluorescence and enzyme immunoassays such as ELISA. A positive result must be interpreted with test sensitivity, specificity, timing and pre-test probability. Include appropriate positive, negative and internal controls; an invalid control result means the run should not be reported until the problem is resolved.","nepali":"Antigen ले antibody सँग विशिष्ट रूपमा जोडिन्छ। प्रयोगशालामा agglutination, precipitation, immunofluorescence र ELISA जस्ता enzyme immunoassay प्रयोग हुन्छन्। Positive नतिजा test sensitivity, specificity, परीक्षणको समय र रोगको पूर्व सम्भावनासँगै व्याख्या गर्नुपर्छ। Positive, negative र internal control राख्नुहोस्; control अमान्य भए समस्या समाधान नभएसम्म नतिजा जारी गर्नु हुँदैन।"}'::jsonb,true),
('bmlt-nhpc-note-27','BMLT','BMLT NHPC Licensing','note','free',27,'{"title":"Histopathology: tissue processing and staining","english":"Routine paraffin histology commonly includes fixation, gross examination, dehydration, clearing, paraffin infiltration, embedding, microtomy, mounting and staining. Formalin is widely used as a routine fixative. Dehydration removes water, clearing replaces alcohol with a solvent compatible with paraffin, and microtomy produces thin sections. Haematoxylin and eosin is the routine stain; special stains are selected for specific organisms or tissue components.","nepali":"सामान्य paraffin histology मा fixation, gross examination, dehydration, clearing, paraffin infiltration, embedding, microtomy, mounting र staining पर्छ। Formalin सामान्य fixative हो। Dehydration ले पानी हटाउँछ, clearing ले alcohol को स्थानमा paraffin सँग मिल्ने solvent ल्याउँछ र microtomy ले पातलो section काट्छ। Haematoxylin and eosin सामान्य stain हो; विशेष जीव वा tissue component का लागि special stain छानिन्छ।"}'::jsonb,true),
('bmlt-nhpc-note-28','BMLT','BMLT NHPC Licensing','note','free',28,'{"title":"Cytology and cervical screening specimens","english":"Cytology examines individual cells and small cell groups rather than the overall tissue architecture. Fine-needle aspiration obtains cells from a lump using a thin needle; cervical cytology samples are collected from the transformation zone according to the screening protocol. Prepare, fix and label slides promptly and ensure patient identifiers match the request. Cytology findings are interpreted using the relevant reporting system and clinical context.","nepali":"Cytology मा tissue को समग्र बनावटभन्दा व्यक्तिगत कोषिका र साना cell group जाँचिन्छ। Fine-needle aspiration ले पातलो सुईबाट गाँठोका कोषिका लिन्छ; cervical cytology नमुना screening protocol अनुसार transformation zone बाट संकलन गरिन्छ। Slide छिटो तयार, fix र label गर्नुहोस् तथा बिरामीको पहिचान request सँग मिलाउनुहोस्। नतिजा सम्बन्धित reporting system र clinical अवस्थाअनुसार व्याख्या गरिन्छ।"}'::jsonb,true),
('bmlt-nhpc-note-29','BMLT','BMLT NHPC Licensing','note','free',29,'{"title":"Clinical parasitology: stool and blood examination","english":"Specimen choice and timing depend on the suspected parasite. Fresh stool may be examined for motile trophozoites; concentration techniques improve detection of some ova and cysts. Thick blood films are more sensitive for detecting malaria parasites at low density, while thin films help identify species and estimate parasitaemia. The cellophane tape test is used for Enterobius vermicularis eggs. Use appropriate biosafety and quality procedures.","nepali":"शंकास्पद परजीवीअनुसार नमुना र संकलन समय छानिन्छ। ताजा दिसामा चलायमान trophozoite हेर्न सकिन्छ; concentration technique ले केही अण्डा र cyst पत्ता लगाउन मद्दत गर्छ। Thick blood film कम संख्यामा रहेका malaria parasite पत्ता लगाउन बढी संवेदनशील हुन्छ; thin film ले species पहिचान र parasitaemia अनुमान गर्न मद्दत गर्छ। Cellophane tape test Enterobius vermicularis का अण्डाका लागि प्रयोग हुन्छ।"}'::jsonb,true),
('bmlt-nhpc-note-30','BMLT','BMLT NHPC Licensing','note','free',30,'{"title":"Laboratory quality management and result reporting","english":"Quality management includes internal quality control, external quality assessment, equipment maintenance, calibration, staff competency, document control and corrective action. A Levey–Jennings chart displays control results over time; apply the laboratory''s validated rules before accepting a run. Verify patient identifiers, units, reference intervals, critical values and plausibility before release. Communicate critical results promptly and document who was informed and when.","nepali":"Laboratory quality management मा internal QC, external quality assessment, उपकरण मर्मत, calibration, कर्मचारी दक्षता, document control र corrective action पर्छ। Levey–Jennings chart ले समयअनुसार QC नतिजा देखाउँछ; run स्वीकार गर्नुअघि प्रयोगशालाको मान्य नियम पालना गर्नुहोस्। नतिजा जारी गर्नुअघि बिरामी पहिचान, unit, reference interval, critical value र plausibility जाँच्नुहोस्। Critical result तुरुन्त सम्बन्धित व्यक्तिलाई जानकारी दिई समय र विवरण अभिलेख गर्नुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-31','BMLT','BMLT NHPC Licensing','note','free',31,'{"title":"Laboratory instrumentation, automation and maintenance","english":"A centrifuge separates components according to density under centrifugal force and must be balanced with matched tubes. A spectrophotometer measures absorbance at a selected wavelength; a pH meter measures hydrogen-ion activity and requires suitable calibration. Automation improves throughput but does not remove the need for specimen checks, internal controls, maintenance, calibration and review of flags or implausible results. Follow manufacturer instructions and document maintenance.","nepali":"Centrifuge ले centrifugal force का आधारमा घनत्वअनुसार पदार्थ छुट्याउँछ र बराबर तौलका tube राखेर balance गर्नुपर्छ। Spectrophotometer ले छानिएको wavelength मा absorbance नाप्छ; pH meter ले hydrogen-ion activity नाप्छ र उपयुक्त calibration चाहिन्छ। Automation ले काम छिटो बनाउँछ तर specimen जाँच, internal control, maintenance, calibration र flag/अस्वाभाविक नतिजाको समीक्षा हटाउँदैन। उत्पादकको निर्देशन पालना गरी maintenance अभिलेख गर्नुहोस्।"}'::jsonb,true),
('bmlt-nhpc-note-32','BMLT','BMLT NHPC Licensing','note','free',32,'{"title":"Blood banking: compatibility and transfusion safety","english":"ABO and RhD typing, antibody screening and compatibility testing help reduce transfusion reactions. A major crossmatch tests recipient plasma against donor red cells according to local policy. Emergency-release red cells may be issued before full compatibility testing only under an authorised protocol. If a transfusion reaction is suspected, stop the transfusion immediately, maintain IV access with compatible fluid according to protocol, recheck patient and unit identity, notify the responsible clinician and blood bank, and send required samples.","nepali":"ABO र RhD grouping, antibody screening र compatibility test ले transfusion reaction को जोखिम घटाउँछन्। Major crossmatch मा recipient plasma र donor RBC को compatibility जाँचिन्छ। पूर्ण compatibility test अघि emergency-release RBC अधिकृत protocol अनुसार मात्र दिन सकिन्छ। Transfusion reaction शंका भए तुरुन्त transfusion रोक्नुहोस्, protocol अनुसार उपयुक्त fluid बाट IV access कायम राख्नुहोस्, बिरामी र unit को पहिचान पुनः जाँच्नुहोस्, जिम्मेवार clinician र blood bank लाई खबर गरी आवश्यक नमुना पठाउनुहोस्।"}'::jsonb,true)
